import { Component } from '@angular/core';
import { LocalStorageService } from '../../services/localStorage/local-storage.service';
import { PerfilUsuarioLogin, UsuarioLogin } from '../auth.model';
import { FormsModule } from '@angular/forms';

import { Router } from '@angular/router';

@Component({
    selector: 'app-select-perfil',
    imports: [
    FormsModule
],
    templateUrl: './select-perfil.component.html',
    styleUrl: './select-perfil.component.css'
})
export class SelectPerfilComponent {
  usuarioLogin: UsuarioLogin = this.storage.getUser()
  perfilSelected: number|undefined
  constructor(
    private storage: LocalStorageService,private router: Router,
  ) {}

  onSelected(){
    const perfil=this.usuarioLogin.perfiles.find((perfil)=> perfil.id==this.perfilSelected)
    if(!perfil) return
    this.storage.setPerfil(perfil)
    this.router.navigate(['/main'])
  }
}
